import sys,collections,heapq,itertools,functools,bisect
def solve(data):
    n,D=map(int,data.split())
    def f(l,r,peak):
        if l==n and r==n:return int(peak==D)
        ans=0
        if l<n and l-r<D:ans+=f(l+1,r,max(peak,l+1-r))
        if r<l:ans+=f(l,r+1,peak)
        return ans
    return f(0,0,0)

if __name__=="__main__":
    a=solve(sys.stdin.buffer.read().decode())
    print(" ".join(map(str,a)) if isinstance(a,(list,tuple)) else a)
